import { client, sessionUser, type Inputs, type Outputs, type SessionUser } from "../client";
import { EmptyPane, ErrorNote, FieldRow, FileInput, FilePreview, FormRow, ListSkeleton, Pagination, Pane, PaneHeader, PaneSkeleton, formatDateTime, formatList, selectClass, splitList, text, toDateTimeInput, yesNo } from "../ui";

type Row = Outputs["posts"]["list"]["data"][number];
type Detail = Outputs["posts"]["get"];
type Input<K extends keyof Inputs["posts"]> = Inputs["posts"][K];

const PAGE_SIZE = 20;
const KEY = ["posts"] as const;

function idOf(raw: string) {
  return raw;
}

function canCreate(user: SessionUser | null): boolean {
  return user !== null;
}

function canUpdate(user: SessionUser | null, row: Detail): boolean {
  return (user !== null && row.author_id === user.id || user !== null && (user as { role?: unknown }).role === "admin");
}

function canDelete(user: SessionUser | null, row: Detail): boolean {
  return (user !== null && row.author_id === user.id || user !== null && (user as { role?: unknown }).role === "admin");
}

function canPublish(user: SessionUser | null, row: Detail): boolean {
  return user !== null && row.author_id === user.id;
}

function canLock(user: SessionUser | null, row: Detail): boolean {
  return user !== null && (user as { role?: unknown }).role === "admin";
}

function canUnlock(user: SessionUser | null, row: Detail): boolean {
  return user !== null && (user as { role?: unknown }).role === "admin";
}

function canArchive(user: SessionUser | null, row: Detail): boolean {
  return user !== null && row.author_id === user.id;
}

function canRestore(user: SessionUser | null, row: Detail): boolean {
  return user !== null && row.author_id === user.id;
}

function canUnpublishAll(user: SessionUser | null): boolean {
  return user !== null && (user as { role?: unknown }).role === "admin";
}

/** Who may open this page */
function canOpen(user: SessionUser | null): boolean {
  return user !== null;
}

function AccessGate({ user }: { user: SessionUser | null }) {
  return (
    <div className="mx-auto max-w-md p-6">
      <Card>
        <CardHeader>
          <CardTitle>{user ? "No access" : "Sign in required"}</CardTitle>
          <CardDescription>{user ? "Your account cannot open this page." : "Sign in to open this page."}</CardDescription>
        </CardHeader>
        {user ? null : (
          <CardContent>
            <Link to="/login" className={buttonVariants()}>
              Sign in
            </Link>
          </CardContent>
        )}
      </Card>
    </div>
  );
}

/** Waits for the session, then renders the page or the gate */
function guarded<P extends object>(Component: (props: P) => ReactNode) {
  return function Guarded(props: P) {
    const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
    if (session.isPending) return <PaneSkeleton />;
    const user = sessionUser(session.data);
    if (!canOpen(user)) return <AccessGate user={user} />;
    return <Component {...props} />;
  };
}

const POSTS_FIELDS = ["title", "content", "published", "author_id", "tags", "cover", "publish_at"] as const;
type PostsField = (typeof POSTS_FIELDS)[number];

type PostsValues = {
  title: string;
  content: string;
  published: boolean;
  author_id: string;
  tags: string;
  cover: string;
  publish_at: string;
};

const EMPTY_POSTS: PostsValues = {
  title: "",
  content: "",
  published: false,
  author_id: "",
  tags: "",
  cover: "",
  publish_at: ""
};

const POSTS_CREATE: readonly PostsField[] = ["title", "content", "published", "tags", "cover", "publish_at"];

function toPostsCreateInput(v: PostsValues): Input<"create"> {
  return {
    title: v.title,
    content: v.content,
    published: v.published,
    tags: (v.tags === "" ? null : splitList(v.tags)),
    cover: (v.cover || null),
    publish_at: (v.publish_at === "" ? null : new Date(v.publish_at).toISOString())
  };
}

const POSTS_UPDATE: readonly PostsField[] = ["title", "content", "published", "author_id", "tags", "cover", "publish_at"];

function toPostsUpdateInput(v: PostsValues): Input<"update">["data"] {
  return {
    title: v.title,
    content: v.content,
    published: v.published,
    author_id: v.author_id,
    tags: (v.tags === "" ? null : splitList(v.tags)),
    cover: (v.cover || null),
    publish_at: (v.publish_at === "" ? null : new Date(v.publish_at).toISOString())
  };
}

function postsFromRow(row: Detail): PostsValues {
  return {
    title: text(row.title),
    content: text(row.content),
    published: row.published ?? false,
    author_id: text(row.author_id),
    tags: formatList(row.tags),
    cover: row.cover?.id ?? "",
    publish_at: toDateTimeInput(row.publish_at)
  };
}

/** Picks a User from the users resource */
function AuthorIdPicker({
  id,
  value,
  onChange,
  allowEmpty
}: {
  id: string;
  value: string;
  onChange: (value: string) => void;
  allowEmpty: boolean;
}) {
  const options = useQuery({ queryKey: ["users", "list", { page_size: 200 }], queryFn: () => client.users.list({ page_size: 200 }) });
  return (
    <select id={id} className={selectClass} value={value} onChange={e => onChange(e.target.value)}>
      {allowEmpty ? <option value="">—</option> : null}
      {(options.data?.data ?? []).map(item => (
        <option key={text(item.id)} value={text(item.id)}>
          {text(item.name)}
        </option>
      ))}
    </select>
  );
}

type PostsSetter = <K extends keyof PostsValues>(key: K, value: PostsValues[K]) => void;

function renderPostsField(field: PostsField, values: PostsValues, set: PostsSetter, current?: Detail | null) {
  switch (field) {
    case "title":
      return (
      <FormRow label="Title" htmlFor="title">
        <Input id="title" type="text" maxLength={200} value={values.title} onChange={e => set("title", e.target.value)} required />
      </FormRow>
      );
    case "content":
      return (
      <FormRow label="Content" htmlFor="content">
        <Textarea id="content" rows={4} value={values.content} onChange={e => set("content", e.target.value)} required />
      </FormRow>
      );
    case "published":
      return (
      <div className="flex items-center gap-2">
        <Checkbox id="published" checked={values.published} onCheckedChange={checked => set("published", checked)} />
        <Label htmlFor="published">Published</Label>
      </div>
      );
    case "author_id":
      return (
      <FormRow label="Author" htmlFor="author_id">
        <AuthorIdPicker id="author_id" value={values.author_id} onChange={value => set("author_id", value)} allowEmpty={false} />
      </FormRow>
      );
    case "tags":
      return (
      <FormRow label="Tags" htmlFor="tags">
        <Input id="tags" type="text" placeholder="comma, separated" value={values.tags} onChange={e => set("tags", e.target.value)} />
      </FormRow>
      );
    case "cover":
      return (
      <FormRow label="Cover" htmlFor="cover">
        <FileInput id="cover" value={values.cover} current={current?.cover} accept="image/*" onChange={fileId => set("cover", fileId)} />
      </FormRow>
      );
    case "publish_at":
      return (
      <FormRow label="Publish At" htmlFor="publish_at">
        <Input id="publish_at" type="datetime-local" value={values.publish_at} onChange={e => set("publish_at", e.target.value)} />
      </FormRow>
      );
  }
}

function PostsForm({
  fields,
  initial,
  current,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly PostsField[];
  initial: PostsValues;
  current?: Detail | null;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: PostsValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<PostsValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: PostsSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderPostsField(field, values, set, current)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

function PostsLayoutInner() {
  const [page, setPage] = useState(1);
  const [archived, setArchived] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const input = { page, page_size: PAGE_SIZE, ...(archived ? { archived: true } : {}) } as Inputs["posts"]["list"];
  const list = useQuery({ queryKey: [...KEY, "list", input], queryFn: () => client.posts.list(input) });
  const matchRoute = useMatchRoute();
  const queryClient = useQueryClient();
  const unpublish_allAction = useMutation({
    mutationFn: (input: Inputs["posts"]["unpublish_all"]) => client.posts.unpublish_all(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  return (
    <div className="flex h-full min-h-0">
      <aside className="flex w-80 shrink-0 flex-col border-r border-border">
        <PaneHeader title="Posts" count={list.data?.page.total}>
          <Button
            variant={archived ? "secondary" : "ghost"}
            size="sm"
            aria-pressed={archived}
            onClick={() => {
              setArchived(current => !current);
              setPage(1);
            }}
          >
            {archived ? "Showing archived" : "Show archived"}
          </Button>
          {canCreate(user) ? (
            <Link to="/posts/new" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="New article">
              <Plus />
            </Link>
          ) : null}
          {canUnpublishAll(user) ? (
            <Button variant="outline" size="sm" disabled={unpublish_allAction.isPending} onClick={() => unpublish_allAction.mutate({})}>
              Unpublish All
            </Button>
          ) : null}
        </PaneHeader>

        <ErrorNote error={unpublish_allAction.error} className="m-4" />
        <div className="min-h-0 flex-1 overflow-y-auto">
          {list.isPending ? (
            <ListSkeleton />
          ) : list.error ? (
            <ErrorNote error={list.error} className="m-4" />
          ) : list.data.data.length === 0 ? (
            <EmptyPane>{archived ? "No archived posts." : "No posts yet."}</EmptyPane>
          ) : (
            <ul className="py-1">
              {list.data.data.map((row: Row) => (
                <li key={text(row.id)}>
                  <Link
                    to="/posts/$id" params={{ id: text(row.id) }}
                    className={cn("block border-l-2 border-transparent px-4 py-2 hover:bg-accent/60", Boolean(matchRoute({ to: "/posts/$id", params: { id: text(row.id) } })) && "border-primary bg-accent", row.archived_at && "text-muted-foreground")}
                  >
                    <div className="truncate text-sm font-medium">{text(row.title) || "Article " + text(row.id)}</div>
                    <div className="truncate text-xs text-muted-foreground">{[(row.published ? "Published" : "Not published"), (row.locked ? "Locked" : "Not locked"), formatDateTime(row.posted_at)].filter(Boolean).join(" · ")}</div>
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </div>
        {list.data ? <Pagination page={page} pageSize={PAGE_SIZE} total={list.data.page.total} onChange={setPage} /> : null}
      </aside>
      <section className="min-w-0 flex-1 overflow-y-auto">
        <Outlet />
      </section>
    </div>
  );
}

function PostsIndexInner() {
  return <EmptyPane>Select an article from the list, or create one.</EmptyPane>;
}

function PostsNewInner() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.posts.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/posts/$id", params: { id: text(row.id) } });
    }
  });
  return (
    <Pane title="New article">
      <PostsForm
        fields={POSTS_CREATE}
        initial={EMPTY_POSTS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toPostsCreateInput(values))}
      />
    </Pane>
  );
}

function PostsDetailInner() {
  const { id: rawId } = useParams({ from: "/posts/$id" });
  const id = idOf(rawId);
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  useEffect(() => {
    setEditing(false);
    setOpenAction(null);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.posts.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["posts"]["update"]) => client.posts.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["posts"]["delete"]) => client.posts.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/posts" });
    }
  });
  const publishAction = useMutation({
    mutationFn: (input: Inputs["posts"]["publish"]) => client.posts.publish(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const lockAction = useMutation({
    mutationFn: (input: Inputs["posts"]["lock"]) => client.posts.lock(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const unlockAction = useMutation({
    mutationFn: (input: Inputs["posts"]["unlock"]) => client.posts.unlock(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const archiveAction = useMutation({
    mutationFn: (input: Inputs["posts"]["archive"]) => client.posts.archive(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const restoreAction = useMutation({
    mutationFn: (input: Inputs["posts"]["restore"]) => client.posts.restore(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.title) || "Article " + text(row.id)}
      actions={
        <>
          {canPublish(user, row) ? (
            <Button variant="outline" size="sm" disabled={publishAction.isPending} onClick={() => publishAction.mutate({ id })}>
              Publish
            </Button>
          ) : null}
          {canLock(user, row) ? (
            <Button variant="outline" size="sm" disabled={lockAction.isPending} onClick={() => lockAction.mutate({ id })}>
              Lock
            </Button>
          ) : null}
          {canUnlock(user, row) ? (
            <Button variant="outline" size="sm" disabled={unlockAction.isPending} onClick={() => unlockAction.mutate({ id })}>
              Unlock
            </Button>
          ) : null}
          {canArchive(user, row) && !row.archived_at ? (
            <Button variant="outline" size="sm" disabled={archiveAction.isPending} onClick={() => archiveAction.mutate({ id })}>
              Archive
            </Button>
          ) : null}
          {canRestore(user, row) && row.archived_at ? (
            <Button variant="outline" size="sm" disabled={restoreAction.isPending} onClick={() => restoreAction.mutate({ id })}>
              Restore
            </Button>
          ) : null}
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this article?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >

      <ErrorNote error={publishAction.error} className="mb-4" />
      <ErrorNote error={lockAction.error} className="mb-4" />
      <ErrorNote error={unlockAction.error} className="mb-4" />
      <ErrorNote error={archiveAction.error} className="mb-4" />
      <ErrorNote error={restoreAction.error} className="mb-4" />
      {editing ? (
        <PostsForm
          fields={POSTS_UPDATE}
          initial={postsFromRow(row)}
          current={row}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toPostsUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Title">{text(row.title) || "—"}</FieldRow>
        <FieldRow label="Content">
          <p className="whitespace-pre-wrap">{text(row.content) || "—"}</p>
        </FieldRow>
        <FieldRow label="Published">{row.published == null ? "—" : <Badge variant={row.published ? "default" : "outline"}>{yesNo(row.published)}</Badge>}</FieldRow>
        <FieldRow label="Locked">{row.locked == null ? "—" : <Badge variant={row.locked ? "default" : "outline"}>{yesNo(row.locked)}</Badge>}</FieldRow>
        <FieldRow label="Cover">
          <FilePreview file={row.cover} />
        </FieldRow>
        <FieldRow label="Tags">
          <span className="flex flex-wrap gap-1">
            {(row.tags ?? []).map(item => (
              <Badge key={text(item)} variant="secondary">
                {text(item)}
              </Badge>
            ))}
          </span>
        </FieldRow>
        <FieldRow label="Posted At">{formatDateTime(row.posted_at) || "—"}</FieldRow>
        <FieldRow label="Author">{(row.author ? text(row.author.name) : text(row.author_id)) || "—"}</FieldRow>
        </dl>
      )}
    </Pane>
  );
}

export const PostsLayout = guarded(PostsLayoutInner);
export const PostsIndex = guarded(PostsIndexInner);
export const PostsNew = guarded(PostsNewInner);
export const PostsDetail = guarded(PostsDetailInner);
